    reg  [8*24-1:0] q_loc, kv_loc;
    always @(*) for (l = 0; l < 8; l = l + 1) begin
        q_loc[24*l +: 24] = {2'b00, vm_waddr[24*l +: 22]};
        kv_loc[24*l +: 24] = {2'b00, kv_waddr[24*l +: 22]};
    end
    wire        own_ar = r_v && stn_dst[1];
    wire [546:0] own_arw = {1'b1, {8'd0, r_addr}, 1'b0, r_last, r_d};      // mode 0: all-reduce
    wire        own_dd = kv_any || q_any;
    wire [547:0] own_ddw = kv_any ? {1'b1, kv_kind, kv_we, kv_loc, kv_wdata, 89'd0}
                                  : {1'b1, 2'd0, su_q_we, q_loc, vm_wdata, 89'd0};
    wire        p_ar = chu_q[1094], p_dd = chu_q[547];
    always @(posedge ck or negedge rst)
        if (!rst) ch_dn_o <= 1095'd0;
        else ch_dn_o <= {p_ar ? chu_q[1094:548] : own_ar ? own_arw : arx_v ? arx_w : 547'd0,
                         p_dd ? chu_q[547:0] : own_dd ? own_ddw : 548'd0};
    wire ch_bad = (p_ar && (own_ar || arx_v)) || (own_ar && arx_v) || (p_dd && own_dd);
    wire dd_bad = ch_bad || (kv_any && q_any) || (kv_any && (kv_kind == 2'd0 || kv_kind == 2'd3));
    // ------------------------------------------------------------------ status and faults
    reg port_fault; reg [2:0] ar_rank; reg ar_last;
    always @(posedge ck or negedge rst)
        if (!rst) begin port_fault <= 1'b0; ar_rank <= 3'd0; ar_last <= 1'b0; end
        else begin
            port_fault <= port_fault | w16_coll | w1_coll | win_bad | red_bad | dd_bad | (ar_v && ar_q[516]) |
                          (c_xc && cmd_q[5:4] != 2'd0) | am_emit_empty | am_mu_fault | (su_go && !su_ready) |
                          g_fault | (c_am && cmd_q[7] && g_arm);
            if (ar_v) begin ar_rank <= ar_q[515:513]; ar_last <= ar_q[512]; end
        end
    // the status token holds the latest source: the gathered cross-die token, or the scalar tree's die token
    reg tok_g;
    wire tsel = g_tok_v || (tok_g && !tok_v);
    // value of the scalar-tree token: the root's own merge value; a non-root slice only sees the broadcast index (0)
    reg [31:0] tok_own_val;
    always @(posedge ck or negedge rst) if (!rst) tok_own_val <= 32'd0; else if (tok_v) tok_own_val <= tok_own ? tok_val : 32'd0;
    // station busy: results outstanding (modes 0-2 count r_v words; the L9 sender counts its l9_o words)
    reg [8:0] stn_left; reg stn_snd;
    wire stn_busy = stn_left != 9'd0;
    // MU-QWEN R4 (qfd_dv_amax_mu): an r_v result word of the previous op is still due after this edge
    assign am_stn_pend = stn_busy && !stn_snd && !(stn_left == 9'd1 && r_v);
    always @(posedge ck or negedge rst)
        if (!rst) begin stn_left <= 9'd0; stn_snd <= 1'b0; end
        else if (c_stn) begin stn_left <= {1'b0, cmd_q[14:7]}; stn_snd <= cmd_q[5:4] == 2'd3; end
        else if (stn_busy && (stn_snd ? l9_o[512] : r_v)) stn_left <= stn_left - 9'd1;
    always @(posedge ck or negedge rst) if (!rst) tok_g <= 1'b0; else if (g_tok_v) tok_g <= 1'b1; else if (tok_v) tok_g <= 1'b0;
    wire any_fault = su_fault | vm_fault | stn_fault | sc_fault | stm_fault | port_fault | hd_fault;
    // MU-QW-AMIX: st[27:26] = user of the token on a tok_v edge (MU_NU > 1), else ar_rank[1:0] (MU_NU 1: always)
    wire [1:0] st_ru = (MU_NU > 1 && (tok_v || g_tok_v)) ? (tsel ? g_user : tok_user) : ar_rank[1:0];
    assign st_n = {ar_v, tsel ? g_tok_val : tok_v ? (tok_own ? tok_val : 32'd0) : tok_own_val, 4'd0 /* sid */, any_fault, su_fault, vm_fault, stn_fault, sc_fault, stm_fault, port_fault,
                    su_idle, sc_busy, su_prog, su_rows, ar_rank[2], st_ru, ar_last, tok_v || g_tok_v,
                    tsel ? g_tok_idx : tok_idx} | (107'(sid_q) << 70);
    // status OR chain toward W5 (registered; the chain end's ag_up_i is the zero identity)
    assign ag_n = agu_q | {stn_busy, any_fault, su_fault, vm_fault, stn_fault, sc_fault, stm_fault, port_fault,
                                 !su_idle, sc_busy};
    initial if (MUT < 0 || (MUT > 12 && MUT != 14)) $fatal(1, "qfd_dv_slice2_lpc: MUT %0d undefined", MUT);
    initial if (HD_W130 != 1) $fatal(1, "qfd_dv_slice2_lpc: the landed re-cut is the HD_W130 = 1 slice");
    initial if (DIR < 0 || DIR > 1) $fatal(1, "qfd_dv_slice2: DIR %0d undefined", DIR);
endmodule


// ---------------------------------------------------------------------------------------------------- u_s: status
module qfd_dv_slice2_lps (
    input  wire          ck,
    input  wire          rst_n,
    input  wire [106:0]  st_n,
    input  wire [9:0]    ag_n,
    input  wire          hd_fault,
    output reg  [106:0]  st,
    output reg  [9:0]    ag_dn_o
);
    reg rs1, rst;                                // the core's regional reset synchroniser (same release edge)
    always @(posedge ck or negedge rst_n)
        if (!rst_n) begin rs1 <= 1'b0; rst <= 1'b0; end
        else begin rs1 <= 1'b1; rst <= rs1; end
    // the heads fault enters any_fault: st[69] and ag_dn_o[8] (OR, as qfd_dv_slice2)
    always @(posedge ck or negedge rst)
        if (!rst) begin st <= 107'd0; ag_dn_o <= 10'd0; end
        else begin
`ifdef OT_LPF_MUT1
            st <= st_n;                          // MUT 1 (bench only): the heads fault is lost
            ag_dn_o <= ag_n;
`elsif OT_LPF_MUT3
            st <= st_n | {37'd0, hd_fault, 69'd0};
            ag_dn_o <= {ag_n[9:2], ag_n[0], ag_n[1]} | {1'b0, hd_fault, 8'd0};   // MUT 3: two ag bits swapped
`else
            st <= st_n | {37'd0, hd_fault, 69'd0};
            ag_dn_o <= ag_n | {1'b0, hd_fault, 8'd0};
`endif
        end
endmodule

// ---------------------------------------------------------------------------------------------------- u_hd: heads
module qfd_dv_slice2_lph #(parameter integer MUT = 0) (
    input  wire          ck,
    input  wire          rst_n,
    input  wire [3:0]    sid,
    input  wire [71:0]   xpf,
    input  wire [379:0]  gi,
    input  wire          sw_v,
    input  wire [23:0]   sw_a,
    input  wire [64*32-1:0] sw_d,
    input  wire          fe_i,
    output wire [515:0]  cw_n0, cw_n1, cw_n2, cw_n3,
    output wire [515:0]  cw_s0, cw_s1, cw_s2, cw_s3,
    output wire          fault
);
    reg rs1, rst;                                // the core's regional reset synchroniser (same release edge)
    always @(posedge ck or negedge rst_n)
        if (!rst_n) begin rs1 <= 1'b0; rst <= 1'b0; end
        else begin rs1 <= 1'b1; rst <= rs1; end
    wire [4*516-1:0] n_d, s_d;
`ifdef OT_LPF_MUT2
    assign {cw_n3, cw_n1, cw_n2, cw_n0} = n_d;   // MUT 2 (bench only): corridor words of column heads 1 / 2 swapped
`else
    assign {cw_n3, cw_n2, cw_n1, cw_n0} = n_d;
`endif
    assign {cw_s3, cw_s2, cw_s1, cw_s0} = s_d;
`ifdef OT_DV_SLICE_HARD
    qfd_dv_heads_w130 u_hd (.ck(ck), .rst_n(rst), .sid(sid),
`else
    qfd_dv_heads_w130 #(.HEAD_MUT((MUT == 8) ? 3 : 0)) u_hd (.ck(ck), .rst_n(rst), .sid(sid),
`endif
        .xpf(xpf), .gi(gi), .sw_v(sw_v), .sw_a(sw_a), .sw_d(sw_d), .fe_i(fe_i), .n_d(n_d), .s_d(s_d), .fault(fault));
endmodule

// ---------------------------------------------------------------------------------------------------- qfd_dv_slice2_e_te: E face (master E = the dn face)
module qfd_dv_slice2_e_te (
    input  wire          ck,                       // region membership only (no state),
    input  wire          rst_n,
    input  wire [1087:0] st_dn_o,
    output wire [1087:0] st_eo,
    input  wire [47:0] sc_dn_o,
    output wire [47:0] sc_eo,
    input  wire [1094:0] ch_dn_o,
    output wire arv_eo,
    output wire [31:0] art_eo,
    output wire arm_eo,
    output wire arl_eo,
    output wire [511:0] ard_eo,
    output wire [547:0] dd_eo,
    input  wire [49:0] cc_o,
    output wire ccv_eo,
    output wire ccm_eo,
    output wire [15:0] ccw_eo,
    output wire [31:0] cct_eo,
    input  wire [513:0] l9_o,
    output wire [513:0] l9_eo
);
    assign st_eo = st_dn_o[1087:0];
    assign sc_eo = sc_dn_o[47:0];
    assign arv_eo = ch_dn_o[1094];
    assign art_eo = ch_dn_o[1093:1062];
    assign arm_eo = ch_dn_o[1061];
    assign arl_eo = ch_dn_o[1060];
    assign ard_eo = ch_dn_o[1059:548];
    assign dd_eo = ch_dn_o[547:0];
    assign ccv_eo = cc_o[49];
    assign ccm_eo = cc_o[48];
    assign ccw_eo = cc_o[47:32];
    assign cct_eo = cc_o[31:0];
    assign l9_eo = l9_o[513:0];
endmodule

// ---------------------------------------------------------------------------------------------------- qfd_dv_slice2_e_tes: E face status outputs (own node: they follow the heads fault, the chains do not wait for it)
module qfd_dv_slice2_e_tes (
